import{_ as i,l as r,o as a,c as l,v as t,p as d,x as o,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"倒排与全文","description":"","frontmatter":{"title":"倒排与全文","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inverted-index-fulltext.md","filePath":"cs/inverted-index-fulltext.md","lastUpdated":1789023840000}'),h={name:"cs/inverted-index-fulltext.md"};function _(f,e,A,E,u,m){const n=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="倒排与全文" tabindex="-1">倒排与全文 <a class="header-anchor" href="#倒排与全文" aria-label="Permalink to &quot;倒排与全文&quot;">​</a></h1><div class="epigraph"><p>倒排表从词项指向出现位置；全文检索是查询该表，不是 `LIKE &#39;%x%&#39;` 扫堆。</p><footer>—— 据 Manning, Raghavan and Schütze, Introduction to IR； Zobel and Moffat 倒排索引；数据库 GIN/全文实践</footer></div><p><a href="/cs/bitmap-index">上一课</a>用值→行位图。本课不 AND 维值。缺口是文本：词项多、文档长、要短语与排名。倒排索引（inverted index）：词典 + 每个词的 posting（文档 id、词频、位置）。关系库用 GIN/GiST 或外置搜索引擎；本课机制，产品课在后课搜索引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>LIKE &#39;%foo%&#39;</code> 不能用 B+ 前缀。全文：分词、停用词、词干，再查 posting 交。短语：位置相邻。缺口是<strong>把文档当分析对象</strong>，行是文档或文档碎片。更新：文档改则要改多个 posting，写放大类似位图但 NDV（词表）极大，常用 LSM 或段+不可变（Lucene 谱系）。</p><p>排名（TF-IDF、BM25）在 posting 上算，不是 SQL <code>ORDER BY length</code>。与向量检索后课不同：这里是稀疏词空间，不是稠密嵌入。</p><p><span class="marginnote">Manning et al. IR 教材。Zobel and Moffat 倒排综述。PostgreSQL tsvector/GIN、InnoDB 全文是库内子集。本课不教语言学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建索引：分词 → 写 posting，压缩差量文档 id。查询：解析查询串 → 取 posting → 交/并/位置过滤 → 打分截断。与 SQL：谓词 <code>@@</code> 下推成倒排扫描，再回表取行。</p><p>事务：库内全文要进同一事务，恢复与 WAL 对齐；外置引擎常最终一致，CDC 后课。</p>',10)),(a(),d(c,null,{default:o(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E6%96%87%E6%A1%A3%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%22%5D%0A%20%20TOK%20--%3E%20INV%5B%22%E8%AF%8D%E9%A1%B9%E5%88%B0%20posting%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20POST%5B%22%E5%8F%96%20posting%20%E4%BA%A4%22%5D%0A%20%20POST%20--%3E%20RANK%5B%22%E6%89%93%E5%88%86%22%5D%0A%20%20RANK%20--%3E%20HEAP%5B%22%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>段：不可变倒排段，查询时多段堆归并，后台合并——LSM 思想在搜索里。zone/跳过：对文档 id 范围可跳过。延迟物化：先 id 再取标题列。</p><p>与位图：低 NDV 可用位图当 posting；词项 posting 通常是压缩整数列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 R 树。也不把向量 ANN 当全文。通配与正则另有三gram 倒排变体，点名。</p><p>后课默认：全文走倒排，不要前导百分号 LIKE。空间索引：几何对象的选择率与邻接，结构换成 R 树等。</p><p>倒排回答「哪些文档含这些词」；关系谓词仍在回表后做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>倒排是词项→位置列表；全文查询是交并与打分。</li><li>更新走段合并或 LSM，与行锁粒度不同。</li><li>空间索引下一课：几何过滤用另一族树。</li><li>出处：Manning et al.；Zobel and Moffat；库内 GIN 实践。</li></ul>',9))])}const D=i(h,[["render",_]]);export{x as __pageData,D as default};
